-- Generated from CT_TI_DATA_ENTRY.xlsm. Requires the existing Supabase schema.
begin;

on conflict (item_no) do update set
  ct_type = excluded.ct_type,
  cust_part_code = excluded.cust_part_code,
  ratio = excluded.ratio,
  rated_voltage = excluded.rated_voltage,
  stc = excluded.stc,
  insulation_level = excluded.insulation_level,
  frequency = excluded.frequency,
  ref_std = excluded.ref_std,
  core1 = excluded.core1,
  core2 = excluded.core2,
  core3 = excluded.core3,
  ct_final_dim = excluded.ct_final_dim,
  ga_drg = excluded.ga_drg,
  ins_class = excluded.ins_class,
  ref_ti = excluded.ref_ti,
  pri_turns = excluded.pri_turns,
  pri_copper = excluded.pri_copper,
  former = excluded.former,
  pri_length = excluded.pri_length,
  pri_weight = excluded.pri_weight,
  sec_terminal = excluded.sec_terminal,
  total_weight = excluded.total_weight,
  default_customer = excluded.default_customer;

on conflict (ti_no) do update set
  ti_date = excluded.ti_date,
  item_no = excluded.item_no,
  wo_number = excluded.wo_number,
  customer_name = excluded.customer_name,
  cus_order_no = excluded.cus_order_no,
  cus_order_date = excluded.cus_order_date,
  quantity = excluded.quantity,
  ct_type = excluded.ct_type,
  cust_part_code = excluded.cust_part_code,
  po_item_no = excluded.po_item_no,
  serial_number = excluded.serial_number,
  ratio = excluded.ratio,
  rated_voltage = excluded.rated_voltage,
  stc = excluded.stc,
  insulation_level = excluded.insulation_level,
  frequency = excluded.frequency,
  ref_std = excluded.ref_std,
  core1 = excluded.core1,
  core2 = excluded.core2,
  core3 = excluded.core3,
  ct_final_dim = excluded.ct_final_dim,
  ga_drg = excluded.ga_drg,
  ins_class = excluded.ins_class,
  ref_ti = excluded.ref_ti,
  pri_turns = excluded.pri_turns,
  pri_copper = excluded.pri_copper,
  former = excluded.former,
  pri_length = excluded.pri_length,
  pri_weight = excluded.pri_weight,
  sec_terminal = excluded.sec_terminal,
  total_weight = excluded.total_weight,
  created_by = excluded.created_by,
  checked_by = excluded.checked_by,
  approved_by = excluded.approved_by;

update public.ct_ti_counter
set current_value = coalesce((
    select max((regexp_match(ti_no, '([0-9]+)$'))[1]::integer)
    from public.ct_ti_records
    where ti_no like left(public.format_ti_no(0), 11) || '%'
      and ti_no ~ '[0-9]+$'
  ), current_value);

commit;
